package com.trimtime.availability;
import jakarta.validation.constraints.*; import java.time.*; import java.util.*;
public final class AvailabilityDtos {private AvailabilityDtos(){} public record HourRequest(@Min(1) @Max(7) int dayOfWeek,@NotNull LocalDate weekStartDate,@NotNull LocalTime startTime,@NotNull LocalTime endTime){} public record BulkHourRequest(@NotNull List<@Min(1) @Max(7) Integer> daysOfWeek,@NotNull LocalDate weekStartDate,@NotNull LocalTime startTime,@NotNull LocalTime endTime){} public record HourResponse(Long id,LocalDate weekStartDate,int dayOfWeek,LocalTime startTime,LocalTime endTime){static HourResponse from(WorkingHour h){return new HourResponse(h.getId(),h.getWeekStartDate(),h.getDayOfWeek(),h.getStartTime(),h.getEndTime());}} public record BreakRequest(@NotNull LocalDate weekStartDate,@Min(1) @Max(7) int dayOfWeek,@NotNull LocalTime startTime,@NotNull LocalTime endTime){} public record BreakResponse(Long id,LocalDate weekStartDate,int dayOfWeek,LocalTime startTime,LocalTime endTime){static BreakResponse from(BarberBreak b){return new BreakResponse(b.getId(),b.getWeekStartDate(),b.getDayOfWeek(),b.getStartTime(),b.getEndTime());}} public record DayOffRequest(@NotNull LocalDate date,LocalTime startTime,LocalTime endTime,@Size(max=255) String reason){} public record DayOffResponse(Long id,LocalDate date,LocalTime startTime,LocalTime endTime,String reason){static DayOffResponse from(DayOff d){return new DayOffResponse(d.getId(),d.getDate(),d.getStartTime(),d.getEndTime(),d.getReason());}}}
